export type Version = Node & {
  __typename?: 'Version';
  dateCreated: Scalars['Datetime']['output'];
  dateUpdated?: Maybe<Scalars['Datetime']['output']>;
  id: Scalars['Int']['output'];
  latest?: Maybe<Scalars['String']['output']>;
  minimum?: Maybe<Scalars['String']['output']>;
  /** A globally unique identifier. Can be used in various places throughout the system to identify this single value. */
  nodeId: Scalars['ID']['output'];
};

export type VersionAggregates = {
  __typename?: 'VersionAggregates';
  /** Mean average aggregates across the matching connection (ignoring before/after/first/last/offset) */
  average?: Maybe<VersionAverageAggregates>;
  /** Distinct count aggregates across the matching connection (ignoring before/after/first/last/offset) */
  distinctCount?: Maybe<VersionDistinctCountAggregates>;
  keys?: Maybe<Array<Maybe<Scalars['String']['output']>>>;
  /** Maximum aggregates across the matching connection (ignoring before/after/first/last/offset) */
  max?: Maybe<VersionMaxAggregates>;
  /** Minimum aggregates across the matching connection (ignoring before/after/first/last/offset) */
  min?: Maybe<VersionMinAggregates>;
  /** Population standard deviation aggregates across the matching connection (ignoring before/after/first/last/offset) */
  stddevPopulation?: Maybe<VersionStddevPopulationAggregates>;
  /** Sample standard deviation aggregates across the matching connection (ignoring before/after/first/last/offset) */
  stddevSample?: Maybe<VersionStddevSampleAggregates>;
  /** Sum aggregates across the matching connection (ignoring before/after/first/last/offset) */
  sum?: Maybe<VersionSumAggregates>;
  /** Population variance aggregates across the matching connection (ignoring before/after/first/last/offset) */
  variancePopulation?: Maybe<VersionVariancePopulationAggregates>;
  /** Sample variance aggregates across the matching connection (ignoring before/after/first/last/offset) */
  varianceSample?: Maybe<VersionVarianceSampleAggregates>;
};

export type VersionAverageAggregates = {
  __typename?: 'VersionAverageAggregates';
  /** Mean average of id across the matching connection */
  id?: Maybe<Scalars['BigFloat']['output']>;
};

/** A condition to be used against `Version` object types. All fields are tested for equality and combined with a logical ‘and.’ */
export type VersionCondition = {
  /** Checks for equality with the object’s `dateCreated` field. */
  dateCreated?: InputMaybe<Scalars['Datetime']['input']>;
  /** Checks for equality with the object’s `dateUpdated` field. */
  dateUpdated?: InputMaybe<Scalars['Datetime']['input']>;
  /** Checks for equality with the object’s `id` field. */
  id?: InputMaybe<Scalars['Int']['input']>;
  /** Checks for equality with the object’s `latest` field. */
  latest?: InputMaybe<Scalars['String']['input']>;
  /** Checks for equality with the object’s `minimum` field. */
  minimum?: InputMaybe<Scalars['String']['input']>;
};

export type VersionDistinctCountAggregates = {
  __typename?: 'VersionDistinctCountAggregates';
  /** Distinct count of dateCreated across the matching connection */
  dateCreated?: Maybe<Scalars['BigInt']['output']>;
  /** Distinct count of dateUpdated across the matching connection */
  dateUpdated?: Maybe<Scalars['BigInt']['output']>;
  /** Distinct count of id across the matching connection */
  id?: Maybe<Scalars['BigInt']['output']>;
  /** Distinct count of latest across the matching connection */
  latest?: Maybe<Scalars['BigInt']['output']>;
  /** Distinct count of minimum across the matching connection */
  minimum?: Maybe<Scalars['BigInt']['output']>;
};

/** A filter to be used against `Version` object types. All fields are combined with a logical ‘and.’ */
export type VersionFilter = {
  /** Checks for all expressions in this list. */
  and?: InputMaybe<Array<VersionFilter>>;
  /** Filter by the object’s `dateCreated` field. */
  dateCreated?: InputMaybe<DatetimeFilter>;
  /** Filter by the object’s `dateUpdated` field. */
  dateUpdated?: InputMaybe<DatetimeFilter>;
  /** Filter by the object’s `id` field. */
  id?: InputMaybe<IntFilter>;
  /** Filter by the object’s `latest` field. */
  latest?: InputMaybe<StringFilter>;
  /** Filter by the object’s `minimum` field. */
  minimum?: InputMaybe<StringFilter>;
  /** Negates the expression. */
  not?: InputMaybe<VersionFilter>;
  /** Checks for any expressions in this list. */
  or?: InputMaybe<Array<VersionFilter>>;
};

