export type ZslSeason = Node & {
  __typename?: 'ZslSeason';
  dateCreated: Scalars['Datetime']['output'];
  dateUpdated?: Maybe<Scalars['Datetime']['output']>;
  endDate: Scalars['Datetime']['output'];
  id: Scalars['Int']['output'];
  name: Scalars['String']['output'];
  /** A globally unique identifier. Can be used in various places throughout the system to identify this single value. */
  nodeId: Scalars['ID']['output'];
  /** Reads a single `ZslPointsStructure` that is related to this `ZslSeason`. */
  pointsStructure?: Maybe<ZslPointsStructure>;
  pointsStructureId: Scalars['Int']['output'];
  startDate: Scalars['Datetime']['output'];
  /** Reads and enables pagination through a set of `User`. */
  usersByZslSeasonResult: ZslSeasonUsersByZslSeasonResultManyToManyConnection;
  /** Reads and enables pagination through a set of `ZslRound`. */
  zslRounds: ZslRoundsConnection;
  /** Reads and enables pagination through a set of `ZslSeasonResult`. */
  zslSeasonResults: ZslSeasonResultsConnection;
};


export type ZslSeasonUsersByZslSeasonResultArgs = {
  after?: InputMaybe<Scalars['Cursor']['input']>;
  before?: InputMaybe<Scalars['Cursor']['input']>;
  condition?: InputMaybe<UserCondition>;
  filter?: InputMaybe<UserFilter>;
  first?: InputMaybe<Scalars['Int']['input']>;
  last?: InputMaybe<Scalars['Int']['input']>;
  offset?: InputMaybe<Scalars['Int']['input']>;
  orderBy?: InputMaybe<Array<UsersOrderBy>>;
};


export type ZslSeasonZslRoundsArgs = {
  after?: InputMaybe<Scalars['Cursor']['input']>;
  before?: InputMaybe<Scalars['Cursor']['input']>;
  condition?: InputMaybe<ZslRoundCondition>;
  filter?: InputMaybe<ZslRoundFilter>;
  first?: InputMaybe<Scalars['Int']['input']>;
  last?: InputMaybe<Scalars['Int']['input']>;
  offset?: InputMaybe<Scalars['Int']['input']>;
  orderBy?: InputMaybe<Array<ZslRoundsOrderBy>>;
};


export type ZslSeasonZslSeasonResultsArgs = {
  after?: InputMaybe<Scalars['Cursor']['input']>;
  before?: InputMaybe<Scalars['Cursor']['input']>;
  condition?: InputMaybe<ZslSeasonResultCondition>;
  filter?: InputMaybe<ZslSeasonResultFilter>;
  first?: InputMaybe<Scalars['Int']['input']>;
  last?: InputMaybe<Scalars['Int']['input']>;
  offset?: InputMaybe<Scalars['Int']['input']>;
  orderBy?: InputMaybe<Array<ZslSeasonResultsOrderBy>>;
};

export type ZslSeasonAggregates = {
  __typename?: 'ZslSeasonAggregates';
  /** Mean average aggregates across the matching connection (ignoring before/after/first/last/offset) */
  average?: Maybe<ZslSeasonAverageAggregates>;
  /** Distinct count aggregates across the matching connection (ignoring before/after/first/last/offset) */
  distinctCount?: Maybe<ZslSeasonDistinctCountAggregates>;
  keys?: Maybe<Array<Maybe<Scalars['String']['output']>>>;
  /** Maximum aggregates across the matching connection (ignoring before/after/first/last/offset) */
  max?: Maybe<ZslSeasonMaxAggregates>;
  /** Minimum aggregates across the matching connection (ignoring before/after/first/last/offset) */
  min?: Maybe<ZslSeasonMinAggregates>;
  /** Population standard deviation aggregates across the matching connection (ignoring before/after/first/last/offset) */
  stddevPopulation?: Maybe<ZslSeasonStddevPopulationAggregates>;
  /** Sample standard deviation aggregates across the matching connection (ignoring before/after/first/last/offset) */
  stddevSample?: Maybe<ZslSeasonStddevSampleAggregates>;
  /** Sum aggregates across the matching connection (ignoring before/after/first/last/offset) */
  sum?: Maybe<ZslSeasonSumAggregates>;
  /** Population variance aggregates across the matching connection (ignoring before/after/first/last/offset) */
  variancePopulation?: Maybe<ZslSeasonVariancePopulationAggregates>;
  /** Sample variance aggregates across the matching connection (ignoring before/after/first/last/offset) */
  varianceSample?: Maybe<ZslSeasonVarianceSampleAggregates>;
};

/** A filter to be used against aggregates of `ZslSeason` object types. */
