  /** Mean average aggregate over matching `ZslSeason` objects. */
  average?: InputMaybe<ZslSeasonAverageAggregateFilter>;
  /** Distinct count aggregate over matching `ZslSeason` objects. */
  distinctCount?: InputMaybe<ZslSeasonDistinctCountAggregateFilter>;
